UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Black Pepper</strong> is a <strong>pungent</strong>, <strong>drying</strong> herb that <strong>stimulates digestion</strong> and is recommended for the <strong>Wet constitution</strong>. It enhances the bioavailability of curcumin from <a href="?herb=203"><strong>Turmeric</strong></a> by making it more soluble (especially in milk); combined with <a href="?herb=203"><strong>Turmeric</strong></a> and <a href="?herb=124"><strong>Ginger</strong></a>, it forms a synergistic <strong>anti-inflammatory</strong> combination for <strong>vaginitis</strong>. Listed as a <strong>lymphatic</strong> herb for <strong>cancer</strong> support.$$
WHERE common_name = 'Black Pepper';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Black Root</strong> is an <strong>astringent</strong> used for <strong>diarrhea</strong>.$$
WHERE common_name = 'Black Root';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Black Walnut</strong> is a <strong>drying</strong>, <strong>anticarcinogenic</strong>, <strong>immunomodulating</strong>, and <strong>chlorophyll-rich</strong> herb rooted in the herbal knowledge exchanged between Cherokee nations and African Americans in North America, and used in traditional Black American herbalism for <strong>digestive ailments</strong> including <strong>diarrhea</strong> and <strong>colic</strong>. It is a key herb in <strong>cancer</strong> care: the leaf is used aggressively (alongside <a href="?herb=35"><strong>Poke Root</strong></a>) in early cancer stages to quickly change the environment; included in anti-cancer formula 1 (early-stage) and formula 2 (more intense); used for <strong>circulatory</strong> and <strong>lymphatic</strong> involvement in Stage 3 cancer; and listed as a <strong>lymphatic</strong> herb for cancer support. The leaf and hull are listed as <strong>anticarcinogenic</strong> - inhibiting, mitigating, preventing, and able to help cure <strong>cancer</strong>. <strong>Black Walnut</strong> is a potent <strong>antifungal</strong> that kills <strong>yeast infections</strong>, <strong>thrush</strong>, <strong>GI candidiasis</strong>, and topical conditions like <strong>athlete's foot</strong> and <strong>toenail fungus</strong>; specifically indicated for <strong>yeast overgrowth</strong> as a drying herb. Also an <strong>anthelmintic</strong> alongside <a href="?herb=97"><strong>Wormwood</strong></a> and <a href="?herb=111"><strong>Clove</strong></a>, removing GI parasites including amoebas, tapeworms, and worms.$$
WHERE common_name = 'Black Walnut';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Blackberry</strong> root is the best <strong>GI astringent</strong> for <strong>acute diarrhea</strong> and <strong>food poisoning</strong> - a <strong>cooling</strong>, <strong>drying</strong> astringent specifically indicated for the <strong>hot, damp diarrhea</strong> tissue state - but use only when needed and temporarily for the acute phase, then transition to elimination herbs. For <strong>childhood diarrhea</strong>, the leaf is more gentle; use as tincture in water, juice, or tea paired with high fluid intake and a simple diet. Also indicated for <strong>influenza diarrhea</strong> and for <strong>diarrhea with slow peristalsis</strong> (alongside bananas and bread); used alongside charcoal for acute digestive complaints. Topically, <strong>Blackberry</strong> is <strong>astringent</strong> and <strong>antimicrobial</strong> for <strong>infected wounds</strong>, applied externally as a tincture or liniment.$$
WHERE common_name = 'Blackberry';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bleeding Heart</strong> Flower Essence is used for <strong>depression due to loss</strong>.$$
WHERE common_name = 'Bleeding Heart';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Blue Cohosh</strong> is a <strong>uterine tonic</strong> and <strong>astringent</strong> (alongside <a href="?herb=157"><strong>Periwinkle</strong></a> and <a href="?herb=25"><strong>Black Cohosh</strong></a>); used for <strong>female reproductive deficiency</strong> as an <strong>anabolic stimulant</strong>.$$
WHERE common_name = 'Blue Cohosh';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Blue Flag</strong> (Iris versicolor) is a <strong>hypolipidemic</strong> herb specific for elevated <strong>LDL</strong> and <strong>VLDL</strong>, for <strong>venous and lymphatic stasis</strong> (Priest and Priest), and for the <strong>hypothyroid picture</strong> of poor fat metabolism and <strong>lymphatic stagnation</strong> - full picture includes: inability to metabolize fats (even vomiting from fats), <strong>nausea headaches</strong>, <strong>light-colored feces</strong>, <strong>heartburn from fats</strong>, <strong>morning nausea</strong>, elevated VLDL and LDL, <strong>pancreatic insufficiency</strong>, and <strong>eczema</strong> with poor fat assimilation. A <strong>berberine</strong> plant for <strong>liver deficiency</strong> to stimulate liver metabolism (alongside <a href="?herb=206"><strong>Milk Thistle</strong></a>; <a href="?herb=35"><strong>Poke Root</strong></a> for extreme cases). Also used for <strong>gut health</strong> and fat metabolism, and for <strong>kidney excess</strong> as a metabolic cooler to dilate renal arteries; stimulates <strong>innate immunity</strong> as a plant specific for stagnation. Featured in Jill Stansbury's Hashimoto's formula: equal parts <a href="?herb=877"><strong>Guggul</strong></a> (Commiphora Mukul), <a href="?herb=118"><strong>Bladderwrack</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=14"><strong>Ginseng</strong></a> (Panax), and <strong>Blue Flag</strong>. Lower dose plant: tincture 10-30 drops 3x/day; decoction 1 tsp:8 oz 3x/day.$$
WHERE common_name = 'Blue Flag';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Blue Vervain</strong> is a <strong>cooling</strong>, MEDIUM <strong>bitter</strong> - gentler than <a href="?herb=102"><strong>Gentian</strong></a> - that works on the upper third of the body, releasing tension and calming thoughts like a water surface; classically described as calming the "choppy waters" of the mind. Specifically indicated for circular thinking, disillusionment, delusions, <strong>jaw</strong> and <strong>shoulder/neck tension</strong>, hyper-focus that won't shut off, and chronic <strong>anxiety</strong> in "type A" constitutions ("type A people will die with a to do list"); effective at higher doses. As an <strong>anxiolytic</strong> for <strong>chronic high cortisol anxiety</strong>: combine with <a href="?herb=2616"><strong>Night-Blooming Cereus</strong></a> for <strong>fear of death</strong>; combine with <a href="?herb=131"><strong>Motherwort</strong></a>; for <strong>PMS and menopausal anxiety</strong> combine with <a href="?herb=178"><strong>Milky Oats</strong></a>. As a <strong>hepatic</strong> bitter it nourishes the <strong>liver</strong> and supports <strong>digestion</strong> - indicated for <strong>hypochlorhydria</strong> and <strong>perimenopause</strong> digestive support (alongside <a href="?herb=172"><strong>Artichoke</strong></a>, orange peel, and <a href="?herb=102"><strong>Gentian</strong></a>); in bitter digestive tincture for <strong>thyroid</strong> and Hashimoto's cases: Blue Vervain + <a href="?herb=127"><strong>Cardamom</strong></a> + <a href="?herb=124"><strong>Ginger</strong></a>. Listed as a <strong>nervine</strong> alongside <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=136"><strong>Catnip</strong></a>, <a href="?herb=137"><strong>Passionflower</strong></a>, and <a href="?herb=142"><strong>Skullcap</strong></a>; also used in euphoric nervine formula for cannabis weaning.$$
WHERE common_name = 'Blue Vervain';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bogbean</strong> (Buckbean) is a <strong>berberine</strong> plant used for <strong>GI deficiency</strong>: for <strong>upper GI deficiency</strong> to stimulate secretions, and for <strong>lower GI deficiency</strong> (constipative type) to stimulate <strong>peristalsis</strong>.$$
WHERE common_name = 'Bogbean';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Boneset</strong> is an <strong>immunostimulant</strong>, <strong>diaphoretic</strong>, <strong>anticatarrhal</strong>, and <strong>antiviral</strong> herb listed in the African American Materia Medica, used during the late antebellum period (post Civil War). As a <strong>diaphoretic</strong> for <strong>fever</strong> and <strong>analgesic/sedative</strong> for <strong>bone aches</strong> in <strong>influenza</strong>, it provides overall <strong>immune support</strong>. Anticatarrhal for <strong>common cold</strong> runny/stuffy nose - used alongside <a href="?herb=309"><strong>Yerba Mansa</strong></a>, <a href="?herb=30"><strong>Goldenseal</strong></a>, and <a href="?herb=21"><strong>Garlic</strong></a>. More commonly used by East Coast herbalists.$$
WHERE common_name = 'Boneset';
